   281→// Validates beacon block according to phase 0 validity conditions.
   282→// - Checks that the parent is in our forkchoice tree.
   283→// - Validates that the proposer signature is valid.
   284→// - Validates that the proposer index is valid.
   285→func (s *Service) validatePhase0Block(ctx context.Context, blk interfaces.ReadOnlySignedBeaconBlock, blockRoot [32]byte) (state.BeaconState, error) {
   286→	if !s.cfg.chain.InForkchoice(blk.Block().ParentRoot()) {
   287→		s.setBadBlock(ctx, blockRoot)
   288→		return nil, blockchain.ErrNotDescendantOfFinalized
   289→	}
   290→
   291→	parentState, err := s.cfg.stateGen.StateByRoot(ctx, blk.Block().ParentRoot())
   292→	if err != nil {
   293→		return nil, err
   294→	}
   295→
   296→	if err := blocks.VerifyBlockSignatureUsingCurrentFork(parentState, blk, blockRoot); err != nil {
   297→		return nil, err
   298→	}
   299→	// In the event the block is more than an epoch ahead from its
   300→	// parent state, we have to advance the state forward.
   301→	parentRoot := blk.Block().ParentRoot()
   302→	parentState, err = transition.ProcessSlotsUsingNextSlotCache(ctx, parentState, parentRoot[:], blk.Block().Slot())
   303→	if err != nil {
   304→		return nil, err
   305→	}
   306→	idx, err := helpers.BeaconProposerIndex(ctx, parentState)
   307→	if err != nil {
   308→		return nil, err
   309→	}
   310→	if blk.Block().ProposerIndex() != idx {
   311→		s.setBadBlock(ctx, blockRoot)
   312→		return nil, errors.New("incorrect proposer index")
   313→	}
   314→	return parentState, nil
   315→}
   316→
   317→func validateDenebBeaconBlock(blk interfaces.ReadOnlyBeaconBlock) error {
   318→	if blk.Version() < version.Deneb {
   319→		return nil
   320→	}
   321→	commits, err := blk.Body().BlobKzgCommitments()
   322→	if err != nil {
   323→		return errors.New("unable to read commitments from deneb block")
   324→	}
   325→	// [REJECT] The length of KZG commitments is less than or equal to the limitation defined in Consensus Layer
   326→	// -- i.e. validate that len(body.signed_beacon_block.message.blob_kzg_commitments) <= MAX_BLOBS_PER_BLOCK
   327→
   328→	maxBlobsPerBlock := params.BeaconConfig().MaxBlobsPerBlock(blk.Slot())
   329→	if len(commits) > maxBlobsPerBlock {
   330→		return errors.Wrapf(errRejectCommitmentLen, "%d > %d", len(commits), maxBlobsPerBlock)
   331→	}
   332→	return nil
   333→}
   334→
   335→// validateBellatrixBeaconBlock validates the block for the Bellatrix fork.
   336→// spec code:
   337→//
   338→//	If the execution is enabled for the block -- i.e. is_execution_enabled(state, block.body) then validate the following:
   339→//	   [REJECT] The block's execution payload timestamp is correct with respect to the slot --
   340→//	   i.e. execution_payload.timestamp == compute_timestamp_at_slot(state, block.slot).
   341→//
   342→//	   If execution_payload verification of block's parent by an execution node is not complete:
   343→//	      [REJECT] The block's parent (defined by block.parent_root) passes all validation (excluding execution
   344→//	       node verification of the block.body.execution_payload).
   345→//	   otherwise:
   346→//	      [IGNORE] The block's parent (defined by block.parent_root) passes all validation (including execution
   347→//	       node verification of the block.body.execution_payload).
   348→func (s *Service) validateBellatrixBeaconBlock(ctx context.Context, parentState state.BeaconState, blk interfaces.ReadOnlyBeaconBlock) error {
   349→	// Error if block and state are not the same version
   350→	if parentState.Version() != blk.Version() {
   351→		return errors.New("block and state are not the same version")
   352→	}
   353→
   354→	body := blk.Body()
   355→	executionEnabled, err := blocks.IsExecutionEnabled(parentState, body)
   356→	if err != nil {
   357→		return err
   358→	}
   359→	if !executionEnabled {
   360→		return nil
   361→	}
   362→
   363→	t, err := slots.StartTime(parentState.GenesisTime(), blk.Slot())
   364→	if err != nil {
   365→		return err
   366→	}
   367→	payload, err := body.Execution()
   368→	if err != nil {
   369→		return err
   370→	}
   371→	if payload == nil || payload.IsNil() {
   372→		return errors.New("execution payload is nil")
   373→	}
   374→	if payload.Timestamp() != uint64(t.Unix()) {
   375→		return errors.New("incorrect timestamp")
   376→	}
   377→
   378→	isParentOptimistic, err := s.cfg.chain.IsOptimisticForRoot(ctx, blk.ParentRoot())
   379→	if err != nil {
   380→		return err
   381→	}
   382→	if isParentOptimistic {
   383→		return ErrOptimisticParent
   384→	}
   385→	return nil
   386→}
   387→
   388→// Verifies the signature of the pending block with respect to the current head state.
   389→func (s *Service) verifyPendingBlockSignature(ctx context.Context, blk interfaces.ReadOnlySignedBeaconBlock, blkRoot [32]byte) (pubsub.ValidationResult, error) {
   390→	roState, err := s.cfg.chain.HeadStateReadOnly(ctx)
   391→	if err != nil {
   392→		return pubsub.ValidationIgnore, err
   393→	}
   394→	// Ignore block in the event of non-existent proposer.
   395→	_, err = roState.ValidatorAtIndexReadOnly(blk.Block().ProposerIndex())
   396→	if err != nil {
   397→		return pubsub.ValidationIgnore, err
   398→	}
   399→	if err := blocks.VerifyBlockSignatureUsingCurrentFork(roState, blk, blkRoot); err != nil {
   400→		s.setBadBlock(ctx, blkRoot)
   401→		return pubsub.ValidationReject, err
   402→	}
   403→	return pubsub.ValidationAccept, nil
   404→}
   405→
   406→// Returns true if the block is not the first block proposed for the proposer for the slot.
   407→func (s *Service) hasSeenBlockIndexSlot(slot primitives.Slot, proposerIdx primitives.ValidatorIndex) bool {
   408→	s.seenBlockLock.RLock()
   409→	defer s.seenBlockLock.RUnlock()
   410→	b := append(bytesutil.Bytes32(uint64(slot)), bytesutil.Bytes32(uint64(proposerIdx))...)
   411→	_, seen := s.seenBlockCache.Get(string(b))
   412→	return seen
   413→}
   414→
   415→// Set block proposer index and slot as seen for incoming blocks.
   416→func (s *Service) setSeenBlockIndexSlot(slot primitives.Slot, proposerIdx primitives.ValidatorIndex) {
   417→	s.seenBlockLock.Lock()
   418→	defer s.seenBlockLock.Unlock()
   419→	b := append(bytesutil.Bytes32(uint64(slot)), bytesutil.Bytes32(uint64(proposerIdx))...)
   420→	s.seenBlockCache.Add(string(b), true)
   421→}
   422→
   423→// Returns true if the block is marked as a bad block.
   424→func (s *Service) hasBadBlock(root [32]byte) bool {
   425→	if features.BlacklistedBlock(root) {
   426→		return true
   427→	}
   428→	s.badBlockLock.RLock()
   429→	defer s.badBlockLock.RUnlock()
   430→	_, seen := s.badBlockCache.Get(string(root[:]))
   431→	return seen
   432→}
   433→
   434→// Set bad block in the cache.
   435→func (s *Service) setBadBlock(ctx context.Context, root [32]byte) {
   436→	s.badBlockLock.Lock()
   437→	defer s.badBlockLock.Unlock()
   438→	if ctx.Err() != nil { // Do not mark block as bad if it was due to context error.
   439→		return
   440→	}
   441→	log.WithField("root", fmt.Sprintf("%#x", root)).Debug("Inserting in invalid block cache")
   442→	s.badBlockCache.Add(string(root[:]), true)
   443→}
   444→
   445→// This captures metrics for block arrival time by subtracts slot start time.
   446→func captureArrivalTimeMetric(genesis time.Time, currentSlot primitives.Slot) error {
   447→	startTime, err := slots.StartTime(genesis, currentSlot)
   448→	if err != nil {
   449→		return err
   450→	}
   451→	ms := prysmTime.Now().Sub(startTime) / time.Millisecond
   452→	arrivalBlockPropagationHistogram.Observe(float64(ms))
   453→	arrivalBlockPropagationGauge.Set(float64(ms))
   454→
   455→	return nil
   456→}
   457→
   458→// isBlockQueueable checks if the slot_time in the block is greater than
   459→// current_time +  MAXIMUM_GOSSIP_CLOCK_DISPARITY. in short, this function
   460→// returns true if the corresponding block should be queued and false if
   461→// the block should be processed immediately.
   462→func isBlockQueueable(genesisTime time.Time, slot primitives.Slot, receivedTime time.Time) bool {
   463→	slotTime, err := slots.StartTime(genesisTime, slot)
   464→	if err != nil {
   465→		return false
   466→	}
   467→
   468→	currentTimeWithDisparity := receivedTime.Add(params.BeaconConfig().MaximumGossipClockDisparityDuration())
   469→	return currentTimeWithDisparity.Unix() < slotTime.Unix()
   470→}
   471→
   472→func getBlockFields(b interfaces.ReadOnlySignedBeaconBlock) logrus.Fields {
   473→	if consensusblocks.BeaconBlockIsNil(b) != nil {
   474→		return logrus.Fields{}
   475→	}
   476→	graffiti := b.Block().Body().Graffiti()
   477→	return logrus.Fields{
   478→		"slot":          b.Block().Slot(),
   479→		"proposerIndex": b.Block().ProposerIndex(),
   480→		"graffiti":      string(graffiti[:]),
   481→		"version":       b.Block().Version(),
   482→	}
   483→}
   484→
   485→// detectAndBroadcastEquivocation checks if the given block is an equivocating block by comparing it with
   486→// the head block. If the blocks are from the same slot and proposer but have different signatures,
   487→// it creates and broadcasts a proposer slashing object after verification.
   488→func (s *Service) detectAndBroadcastEquivocation(ctx context.Context, blk interfaces.ReadOnlySignedBeaconBlock) error {
   489→	slot := blk.Block().Slot()
   490→	proposerIndex := blk.Block().ProposerIndex()
   491→
   492→	// Get head block for comparison
   493→	headBlock, err := s.cfg.chain.HeadBlock(ctx)
   494→	if err != nil {
   495→		return errors.Wrap(err, "could not get head block")
   496→	}
   497→
   498→	// Only proceed if this block is from same slot and proposer as head
   499→	if headBlock.Block().Slot() != slot || headBlock.Block().ProposerIndex() != proposerIndex {
   500→		return nil
   501→	}
   502→
   503→	// Compare signatures
   504→	sig1 := blk.Signature()
   505→	sig2 := headBlock.Signature()
   506→
   507→	// If signatures match, these are the same block
   508→	if sig1 == sig2 {
   509→		return nil
   510→	}
   511→
   512→	// Extract headers for slashing
   513→	header1, err := blk.Header()
   514→	if err != nil {
   515→		return errors.Wrap(err, "could not get header from new block")
   516→	}
   517→	header2, err := headBlock.Header()
   518→	if err != nil {
   519→		return errors.Wrap(err, "could not get header from head block")
   520→	}
   521→
   522→	slashing := &ethpb.ProposerSlashing{
   523→		Header_1: header1,
   524→		Header_2: header2,
   525→	}
   526→
   527→	// Get state for verification
   528→	headState, err := s.cfg.chain.HeadStateReadOnly(ctx)
   529→	if err != nil {
   530→		return errors.Wrap(err, "could not get head state")
   531→	}
   532→
   533→	// Verify the slashing against current state
   534→	if err := blocks.VerifyProposerSlashing(headState, slashing); err != nil {
   535→		if errors.Is(err, blocks.ErrCouldNotVerifyBlockHeader) {
   536→			return errors.Wrap(ErrSlashingSignatureFailure, err.Error())
   537→		}
   538→		return errors.Wrap(err, "could not verify proposer slashing")
   539→	}
   540→
   541→	// Broadcast if verification passes
   542→	if !features.Get().DisableBroadcastSlashings {
   543→		if err := s.cfg.p2p.Broadcast(ctx, slashing); err != nil {
   544→			return errors.Wrap(err, "could not broadcast slashing object")
   545→		}
   546→	}
   547→
   548→	// Insert into slashing pool
   549→	if err := s.cfg.slashingPool.InsertProposerSlashing(ctx, headState, slashing); err != nil {
   550→		return errors.Wrap(err, "could not insert proposer slashing into pool")
   551→	}
   552→
   553→	return nil
   554→}
   555→

