    30→                                  "consensus-types/primitives.ValidatorIndex" ];
    31→
    32→  // 32 byte merkle tree root of the parent ssz encoded block.
    33→  bytes parent_root = 3 [ (ethereum.eth.ext.ssz_size) = "32" ];
    34→
    35→  // 32 byte merkle tree root of the resulting ssz encoded state after
    36→  // processing this block.
    37→  bytes state_root = 4 [ (ethereum.eth.ext.ssz_size) = "32" ];
