message BlobSidecars {
  repeated BlobSidecar sidecars = 1
      [ (ethereum.eth.ext.ssz_max) = "max_blobs_per_block.size" ];
}

message BlobSidecar {
  uint64 index = 1;
  bytes blob = 2 [ (ethereum.eth.ext.ssz_size) = "blob.size" ];
  bytes kzg_commitment = 3 [ (ethereum.eth.ext.ssz_size) = "48" ];
  bytes kzg_proof = 4 [ (ethereum.eth.ext.ssz_size) = "48" ];
  SignedBeaconBlockHeader signed_block_header = 5;
  repeated bytes commitment_inclusion_proof = 6
      [ (ethereum.eth.ext.ssz_size) =
            "kzg_commitment_inclusion_proof_depth.size,32" ];
}

// ----------------------------------------------------------------------------
// Electra
// ----------------------------------------------------------------------------

message SignedBeaconBlockContentsElectra {
  SignedBeaconBlockElectra block = 1;
  repeated bytes kzg_proofs = 2 [
    (ethereum.eth.ext.ssz_size) = "?,48",
    (ethereum.eth.ext.ssz_max) = "4096"
  ];
  repeated bytes blobs = 3 [
    (ethereum.eth.ext.ssz_size) = "?,blob.size",
    (ethereum.eth.ext.ssz_max) = "4096"
  ];

