     1→package blocks
     2→
     3→import (
     4→	field_params "github.com/OffchainLabs/prysm/v6/config/fieldparams"
     5→	"github.com/OffchainLabs/prysm/v6/config/params"
     6→	"github.com/OffchainLabs/prysm/v6/consensus-types/interfaces"
     7→	"github.com/OffchainLabs/prysm/v6/container/trie"
     8→	"github.com/OffchainLabs/prysm/v6/encoding/ssz"
     9→	"github.com/OffchainLabs/prysm/v6/runtime/version"
    10→	"github.com/pkg/errors"
    11→	"github.com/prysmaticlabs/gohashtree"
    12→)
    13→
    14→const (
    15→	bodyLength    = 13 // The number of elements in the BeaconBlockBody Container for Electra
    16→	logBodyLength = 4  // The log 2 of bodyLength
    17→	kzgPosition   = 11 // The index of the KZG commitment list in the Body
    18→	kzgRootIndex  = 54 // The Merkle index of the KZG commitment list's root in the Body's Merkle tree
    19→	KZGOffset     = kzgRootIndex * field_params.MaxBlobCommitmentsPerBlock
    20→)
    21→
    22→var (
    23→	errInvalidIndex          = errors.New("index out of bounds")
    24→	errInvalidBodyRoot       = errors.New("invalid Beacon Block Body root")
    25→	errInvalidInclusionProof = errors.New("invalid KZG commitment inclusion proof")
    26→)
    27→
    28→// MerkleProofComponents contains pre-computed components for efficient proof generation
    29→type MerkleProofComponents struct {
    30→	kzgSubtree    *trie.SparseMerkleTrie
    31→	topLevelProof [][]byte
    32→}
    33→
    34→// VerifyKZGInclusionProof verifies the Merkle proof in a Blob sidecar against
    35→// the beacon block body root.
    36→func VerifyKZGInclusionProof(blob ROBlob) error {
    37→	if blob.SignedBlockHeader == nil {
    38→		return errNilBlockHeader
    39→	}
    40→	if blob.SignedBlockHeader.Header == nil {
    41→		return errNilBlockHeader
    42→	}
    43→	root := blob.SignedBlockHeader.Header.BodyRoot
    44→	if len(root) != field_params.RootLength {
    45→		return errInvalidBodyRoot
    46→	}
    47→	chunks := makeChunk(blob.KzgCommitment)
    48→	gohashtree.HashChunks(chunks, chunks)
    49→	verified := trie.VerifyMerkleProof(root, chunks[0][:], blob.Index+KZGOffset, blob.CommitmentInclusionProof)
    50→	if !verified {
    51→		return errInvalidInclusionProof
    52→	}
    53→	return nil
    54→}
    55→
    56→// MerkleProofKZGCommitment constructs a Merkle proof of inclusion of the KZG
    57→// commitment of index `index` into the Beacon Block with the given `body`
    58→func MerkleProofKZGCommitment(body interfaces.ReadOnlyBeaconBlockBody, index int) ([][]byte, error) {
    59→	bodyVersion := body.Version()
    60→	if bodyVersion < version.Deneb {
    61→		return nil, errUnsupportedBeaconBlockBody
    62→	}
    63→	commitments, err := body.BlobKzgCommitments()
    64→	if err != nil {
    65→		return nil, err
    66→	}
    67→	proof, err := bodyProof(commitments, index)
    68→	if err != nil {
    69→		return nil, err
    70→	}
    71→	membersRoots, err := topLevelRoots(body)
    72→	if err != nil {
    73→		return nil, err
    74→	}
    75→	sparse, err := trie.GenerateTrieFromItems(membersRoots, logBodyLength)
    76→	if err != nil {
    77→		return nil, err
    78→	}
    79→	topProof, err := sparse.MerkleProof(kzgPosition)
    80→	if err != nil {
    81→		return nil, err
    82→	}
    83→	// sparse.MerkleProof always includes the length of the slice this is
    84→	// why we remove the last element that is not needed in topProof
    85→	proof = append(proof, topProof[:len(topProof)-1]...)
    86→	return proof, nil
    87→}
    88→
    89→// PrecomputeMerkleProofComponents pre-computes the expensive parts of Merkle proof generation
    90→// that are shared across all blob indices for a given block body.
    91→func PrecomputeMerkleProofComponents(body interfaces.ReadOnlyBeaconBlockBody) (*MerkleProofComponents, error) {
    92→	bodyVersion := body.Version()
    93→	if bodyVersion < version.Deneb {
    94→		return nil, errUnsupportedBeaconBlockBody
    95→	}
    96→
    97→	// Pre-compute KZG subtree
    98→	commitments, err := body.BlobKzgCommitments()
    99→	if err != nil {
   100→		return nil, err
   101→	}
   102→
   103→	// No work needed if there are no commitments
   104→	if len(commitments) == 0 {
   105→		return nil, nil
   106→	}
   107→
   108→	leaves := LeavesFromCommitments(commitments)
   109→	kzgSubtree, err := trie.GenerateTrieFromItems(leaves, field_params.LogMaxBlobCommitments)
   110→	if err != nil {
   111→		return nil, err
   112→	}
   113→
   114→	// Pre-compute top-level components
   115→	membersRoots, err := topLevelRoots(body)
   116→	if err != nil {
   117→		return nil, err
   118→	}
   119→	topLevelTrie, err := trie.GenerateTrieFromItems(membersRoots, logBodyLength)
   120→	if err != nil {
   121→		return nil, err
   122→	}
   123→	topLevelProof, err := topLevelTrie.MerkleProof(kzgPosition)
   124→	if err != nil {
   125→		return nil, err
   126→	}
   127→	// Remove the last element that is not needed in topProof
   128→	topLevelProof = topLevelProof[:len(topLevelProof)-1]
   129→
   130→	return &MerkleProofComponents{
   131→		kzgSubtree:    kzgSubtree,
   132→		topLevelProof: topLevelProof,
   133→	}, nil
   134→}
   135→
   136→// MerkleProofKZGCommitmentFromComponents constructs a Merkle proof for a specific index
   137→// using pre-computed components, avoiding redundant calculations.
   138→func MerkleProofKZGCommitmentFromComponents(components *MerkleProofComponents, index int) ([][]byte, error) {
   139→	// Generate index-specific proof from pre-computed KZG subtree
   140→	subtreeProof, err := components.kzgSubtree.MerkleProof(index)
   141→	if err != nil {
   142→		return nil, err
   143→	}
   144→
   145→	// Combine with pre-computed top-level proof
   146→	proof := append(subtreeProof, components.topLevelProof...)
   147→	return proof, nil
   148→}
   149→
   150→// MerkleProofKZGCommitments constructs a Merkle proof of inclusion of the KZG
   151→// commitments into the Beacon Block with the given `body`
   152→func MerkleProofKZGCommitments(body interfaces.ReadOnlyBeaconBlockBody) ([][]byte, error) {
   153→	bodyVersion := body.Version()
